{"status":"candidate","chosen_option":"offline_fenwick","assumptions":["Storing up to q operations and their update values in memory is acceptable; the task gives no explicit memory limit."],"observations":[{"statement":"The program must process insertions, deletions, and one-based kth-smallest queries, counting duplicates and printing NONE for invalid ranks.","source_ids":["task"]},{"statement":"Both public examples require NONE for an invalid query rank; the second also includes deletions of absent values.","source_ids":["public1","public2"]}],"artifact":{"code":"import sys


def main():
    inp = sys.stdin.buffer
    first = inp.readline()
    if not first:
        return
    q = int(first)

    operations = []
    values = []
    for _ in range(q):
        op, arg = inp.readline().split()
        x = int(arg)
        operations.append((op, x))
        if op != b'?':
            values.append(x)

    values = sorted(set(values))
    index_of = {x: i for i, x in enumerate(values)}
    n = len(values)
    bit = [0] * (n + 1)
    counts = [0] * n

    def add(i, delta):
        i += 1
        while i <= n:
            bit[i] += delta
            i += i & -i

    def kth(k):
        # Return the zero-based compressed index containing rank k.
        pos = 0
        step = 1 << (n.bit_length() - 1)
        while step:
            nxt = pos + step
            if nxt <= n and bit[nxt] < k:
                pos = nxt
                k -= bit[nxt]
            step >>= 1
        return pos

    output = []
    size = 0
    for op, x in operations:
        if op == b'+':
            i = index_of[x]
            counts[i] += 1
            add(i, 1)
            size += 1
        elif op == b'-':
            i = index_of[x]
            if counts[i] > 0:
                counts[i] -= 1
                add(i, -1)
                size -= 1
        else:
            if x < 1 or x > size:
                output.append('NONE')
            else:
                output.append(str(values[kth(x)]))

    sys.stdout.write('\n'.join(output))
    if output:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()
